 61→export default function ChatIndex({ conversation }: Props) {
 62→    const { auth } = usePage<SharedData>().props;
 63→    const [messages, setMessages] = useState<Message[]>(conversation.messages || []);
 64→    const [input, setInput] = useState('');
 65→    const [typing, setTyping] = useState(false);
 66→    const scrollRef = useRef<HTMLDivElement>(null);
 67→    const inputRef = useRef<HTMLInputElement>(null);
 68→
 69→    useEffect(() => {
 70→        scrollRef.current?.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
 71→    }, [messages, typing]);
 72→
 73→    const sendMessage = async (text: string) => {
 74→        if (!text.trim()) return;
 75→        setInput('');
 76→
 77→        const userMsg: Message = {
 78→            id: Date.now(),
 79→            role: 'user',
 80→            content: text.trim(),
 81→            quick_replies: null,
 82→            created_at: new Date().toISOString(),
 83→        };
 84→        setMessages((prev) => [...prev, userMsg]);
 85→        setTyping(true);
 86→
 87→        try {
 88→            const res = await fetch('/chat/messages', {
 89→                method: 'POST',
 90→                headers: {
 91→                    'Content-Type': 'application/json',
 92→                    'X-CSRF-TOKEN': document.querySelector<HTMLMetaElement>('meta[name="csrf-token"]')?.content || '',
 93→                    'Accept': 'application/json',
 94→                },
 95→                body: JSON.stringify({ message: text.trim() }),
 96→            });
 97→
 98→            if (res.ok) {
 99→                const data = await res.json();
100→                await new Promise((r) => setTimeout(r, 500 + Math.random() * 1000));
101→                setMessages((prev) => [...prev, data.message]);
102→            }
103→        } catch {
104→            setMessages((prev) => [...prev, {
105→                id: Date.now() + 1,
106→                role: 'assistant',
