  1→export type QueryParams = {
  2→    [key: string]:
  3→        | string
  4→        | number
  5→        | boolean
  6→        | (string | number)[]
  7→        | null
  8→        | undefined
  9→        | QueryParams;
 10→};
 11→
 12→type Method = "get" | "post" | "put" | "delete" | "patch" | "head" | "options";
 13→type UrlDefaults = Record<string, unknown>;
 14→
 15→let urlDefaults: () => UrlDefaults = () => ({});
 16→
 17→export type RouteDefinition<TMethod extends Method | Method[]> = {
 18→    url: string;
 19→} & (TMethod extends Method[] ? { methods: TMethod } : { method: TMethod });
 20→
 21→export type RouteFormDefinition<TMethod extends Method> = {
 22→    action: string;
 23→    method: TMethod;
 24→};
 25→
 26→export type RouteQueryOptions = {
 27→    query?: QueryParams;
 28→    mergeQuery?: QueryParams;
 29→};
 30→
 31→const getValue = (value: string | number | boolean) => {
 32→    if (value === true) {
 33→        return "1";
 34→    }
 35→
 36→    if (value === false) {
 37→        return "0";
 38→    }
 39→
 40→    return value.toString();
 41→};
 42→
 43→const addNestedParams = (
 44→    obj: QueryParams,
 45→    prefix: string,
 46→    params: URLSearchParams,
 47→) => {
 48→    Object.entries(obj).forEach(([subKey, value]) => {
 49→        if (value === undefined) return;
 50→
 51→        const paramKey = `${prefix}[${subKey}]`;
 52→
 53→        if (Array.isArray(value)) {
 54→            value.forEach((v) => params.append(`${paramKey}[]`, getValue(v)));
 55→        } else if (value !== null && typeof value === "object") {
 56→            addNestedParams(value, paramKey, params);
 57→        } else if (["string", "number", "boolean"].includes(typeof value)) {
 58→            params.set(paramKey, getValue(value as string | number | boolean));
 59→        }
 60→    });
 61→};
 62→
 63→export const queryParams = (options?: RouteQueryOptions) => {
 64→    if (!options || (!options.query && !options.mergeQuery)) {
 65→        return "";
 66→    }
 67→
 68→    const query = options.query ?? options.mergeQuery;
 69→    const includeExisting = options.mergeQuery !== undefined;
 70→
 71→    const params = new URLSearchParams(
 72→        includeExisting && typeof window !== "undefined"
 73→            ? window.location.search
 74→            : "",
 75→    );
 76→
 77→    for (const key in query) {
 78→        const queryValue = query[key];
 79→
 80→        if (queryValue === undefined || queryValue === null) {
 81→            params.delete(key);
 82→            continue;
 83→        }
 84→
 85→        if (Array.isArray(queryValue)) {
 86→            if (params.has(`${key}[]`)) {
 87→                params.delete(`${key}[]`);
 88→            }
 89→
 90→            queryValue.forEach((value) => {
 91→                params.append(`${key}[]`, value.toString());
 92→            });
 93→        } else if (typeof queryValue === "object") {
 94→            params.forEach((_, paramKey) => {
 95→                if (paramKey.startsWith(`${key}[`)) {
 96→                    params.delete(paramKey);
 97→                }
 98→            });
 99→
100→            addNestedParams(queryValue, key, params);
101→        } else {
102→            params.set(key, getValue(queryValue));
103→        }
104→    }
105→
106→    const str = params.toString();
107→
108→    return str.length > 0 ? `?${str}` : "";
109→};
110→
111→export const setUrlDefaults = (params: UrlDefaults | (() => UrlDefaults)) => {
112→    urlDefaults = typeof params === "function" ? params : () => params;
113→};
114→
115→export const addUrlDefault = (
116→    key: string,
117→    value: string | number | boolean,
118→) => {
119→    const params = urlDefaults();
120→    params[key] = value;
121→
122→    urlDefaults = () => params;
123→};
124→
125→export const applyUrlDefaults = <T extends UrlDefaults | undefined>(
126→    existing: T,
127→): T => {
128→    const existingParams = { ...(existing ?? ({} as UrlDefaults)) };
129→    const defaultParams = urlDefaults();
130→
131→    for (const key in defaultParams) {
132→        if (
133→            existingParams[key] === undefined &&
134→            defaultParams[key] !== undefined
135→        ) {
136→            (existingParams as Record<string, unknown>)[key] =
137→                defaultParams[key];
138→        }
139→    }
140→
141→    return existingParams as T;
142→};
143→
144→export const validateParameters = (
145→    args: Record<string, unknown> | undefined,
146→    optional: string[],
147→) => {
148→    const missing = optional.filter((key) => !args?.[key]);
149→    const expectedMissing = optional.slice(missing.length * -1);
150→
151→    for (let i = 0; i < missing.length; i++) {
152→        if (missing[i] !== expectedMissing[i]) {
153→            throw Error(
154→                "Unexpected optional parameters missing. Unable to generate a URL.",
155→            );
156→        }
157→    }
158→};
