300→    const [step, setStep] = useState(0);
301→    const [subExploitation, setSubExploitation] = useState<SubExploitation | null>(null);
302→    const [motherId, setMotherId] = useState<number | null>(null);
303→    const [fatherId, setFatherId] = useState<number | null>(null);
304→    const [calves, setCalves] = useState<CalfData[]>([]);
305→    const [submitting, setSubmitting] = useState(false);
306→    const [result, setResult] = useState<{ reference_code: string; assigned_crotals: string[] } | null>(null);
307→
308→    const today = new Date().toISOString().split('T')[0];
309→
310→    const handleSubSelect = (sub: SubExploitation) => {
311→        setSubExploitation(sub);
312→        const motherBreed = sub.animals.find((a) => a.sex === 'female')?.breed || '';
313→        setCalves([{ sex: 'female', breed: motherBreed, name: '', birth_date: today }]);
314→        setStep(1);
315→    };
316→
317→    const handleMotherSelect = (id: number) => {
318→        setMotherId(id);
319→        const mother = subExploitation?.animals.find((a) => a.id === id);
320→        if (mother) {
321→            setCalves((prev) => prev.map((c) => ({ ...c, breed: mother.breed })));
322→        }
323→    };
324→
325→    const handleSubmit = async () => {
326→        if (!subExploitation || !motherId) return;
327→        setSubmitting(true);
328→
329→        router.post('/nacimientos', {
330→            sub_exploitation_id: subExploitation.id,
331→            mother_id: motherId,
332→            father_id: fatherId,
333→            birth_type: calves.length > 1 ? 'multiple' : 'simple',
334→            calf_count: calves.length,
335→            calves: calves.map((c) => ({
336→                sex: c.sex,
337→                breed: c.breed,
338→                name: c.name || null,
339→                birth_date: c.birth_date,
340→            })),
341→        }, {
342→            onSuccess: (page: any) => {
343→                const flash = page.props?.flash;
344→                setResult({
345→                    reference_code: flash?.reference_code || 'NC-2026-048-00001',
346→                    assigned_crotals: flash?.assigned_crotals || [],
347→                });
348→                setStep(5);
349→            },
350→            onError: () => setSubmitting(false),
351→        });
352→    };
353→
354→    const canNext = () => {
355→        if (step === 0) return !!subExploitation;
356→        if (step === 1) return !!motherId;
357→        if (step === 3) return calves.every((c) => c.birth_date && c.sex && c.breed);
358→        return true;
359→    };
360→
361→    return (
362→        <AppLayout breadcrumbs={breadcrumbs}>
363→            <Head title="Comunicar Nacimiento" />
364→            <div className="flex flex-col gap-5 p-6">
365→                {step < 5 && (
366→                    <>
367→                        <ProgressBar currentStep={step} />
368→                        <p className="text-xs font-semibold uppercase tracking-[2px] text-[#757575]">Paso {step + 1} de 6</p>
369→                    </>
370→                )}
371→
372→                {step === 0 && <Step1 subExploitations={exploitation.sub_exploitations} onSelect={handleSubSelect} />}
373→                {step === 1 && subExploitation && <Step2 animals={subExploitation.animals} selectedId={motherId} onSelect={handleMotherSelect} />}
374→                {step === 2 && subExploitation && <Step3 animals={subExploitation.animals} selectedId={fatherId} onSelect={setFatherId} onSkip={() => { setFatherId(null); setStep(3); }} />}
375→                {step === 3 && subExploitation && (
376→                    <Step4
377→                        motherBreed={subExploitation.animals.find((a) => a.id === motherId)?.breed || ''}
378→                        calves={calves}
379→                        onUpdate={setCalves}
380→                    />
381→                )}
382→                {step === 4 && subExploitation && (
383→                    <Step5 sub={subExploitation} mother={motherId!} father={fatherId} calves={calves} animals={subExploitation.animals} />
384→                )}
385→                {step === 5 && result && <Step6 referenceCode={result.reference_code} assignedCrotals={result.assigned_crotals} />}
386→
387→                {step > 0 && step < 5 && (
388→                    <div className="flex gap-2">
389→                        <button onClick={() => setStep(step - 1)} className="flex items-center gap-1 border-2 border-black px-4 py-3 text-sm font-semibold">
390→                            <ChevronLeft className="size-4" /> Atrás
391→                        </button>
392→                        <div className="flex-1" />
393→                        {step < 4 ? (
394→                            <button
395→                                onClick={() => setStep(step + 1)}
396→                                disabled={!canNext()}
397→                                className="flex items-center gap-1 bg-[#E53935] px-6 py-3 text-sm font-bold text-white disabled:opacity-50"
398→                            >
399→                                Siguiente <ChevronRight className="size-4" />
400→                            </button>
401→                        ) : (
402→                            <button
403→                                onClick={handleSubmit}
404→                                disabled={submitting}
405→                                className="flex items-center gap-1 bg-[#E53935] px-6 py-3 text-sm font-bold text-white disabled:opacity-50"
406→                            >
407→                                {submitting ? 'Enviando...' : 'Enviar comunicación'}
408→                            </button>
409→                        )}
410→                    </div>
411→                )}
412→            </div>
413→        </AppLayout>
414→    );
415→}
