  5→use App\Http\Requests\StoreBirthRegistrationRequest;
  6→use App\Models\Animal;
  7→use App\Models\BirthRegistration;
  8→use App\Models\SubExploitation;
  9→use Illuminate\Http\RedirectResponse;
 10→use Illuminate\Http\Request;
 11→use Illuminate\Support\Facades\DB;
 12→use Inertia\Inertia;
 13→use Inertia\Response;
 14→
 15→class BirthRegistrationController extends Controller
 16→{
 17→    public function create(Request $request): Response
 18→    {
 19→        $exploitation = $request->user()
 20→            ->exploitations()
 21→            ->with(['subExploitations.animals'])
 22→            ->firstOrFail();
 23→
 24→        return Inertia::render('nacimientos/crear', [
 25→            'exploitation' => $exploitation,
 26→        ]);
 27→    }
 28→
 29→    public function store(StoreBirthRegistrationRequest $request): RedirectResponse
 30→    {
 31→        $validated = $request->validated();
 32→
 33→        $subExploitation = SubExploitation::findOrFail($validated['sub_exploitation_id']);
 34→        $mother = Animal::findOrFail($validated['mother_id']);
 35→
 36→        return DB::transaction(function () use ($validated, $subExploitation, $mother): RedirectResponse {
 37→            $referenceCode = $this->generateReferenceCode();
 38→
 39→            $birthRegistration = BirthRegistration::create([
 40→                'sub_exploitation_id' => $validated['sub_exploitation_id'],
 41→                'mother_id' => $validated['mother_id'],
 42→                'father_id' => $validated['father_id'] ?? null,
 43→                'birth_type' => $validated['birth_type'],
 44→                'calf_count' => count($validated['calves']),
 45→                'status' => 'submitted',
 46→                'submitted_at' => now(),
 47→                'reference_code' => $referenceCode,
 48→            ]);
 49→
 50→            $createdCalves = [];
 51→
 52→            foreach ($validated['calves'] as $calfData) {
 53→                $assignedCrotal = $this->generateCrotalCode();
 54→
 55→                $calf = $birthRegistration->calves()->create([
 56→                    'sex' => $calfData['sex'],
 57→                    'breed' => $calfData['breed'],
 58→                    'name' => $calfData['name'] ?? null,
 59→                    'birth_date' => $calfData['birth_date'],
 60→                    'assigned_crotal' => $assignedCrotal,
 61→                ]);
 62→
 63→                Animal::create([
 64→                    'sub_exploitation_id' => $subExploitation->id,
 65→                    'crotal_code' => $assignedCrotal,
 66→                    'species' => $subExploitation->species,
 67→                    'breed' => $calfData['breed'],
 68→                    'sex' => $calfData['sex'],
 69→                    'name' => $calfData['name'] ?? null,
 70→                    'birth_date' => $calfData['birth_date'],
 71→                    'mother_id' => $mother->id,
 72→                    'father_id' => $validated['father_id'] ?? null,
 73→                    'status' => 'active',
 74→                ]);
 75→
 76→                $createdCalves[] = [
 77→                    'name' => $calfData['name'] ?? null,
 78→                    'sex' => $calfData['sex'],
 79→                    'crotal' => $assignedCrotal,
 80→                ];
 81→            }
 82→
 83→            $subExploitation->increment('current_capacity', count($validated['calves']));
 84→
 85→            return redirect()->route('nacimientos.create')->with('success', [
 86→                'message' => 'Nacimiento registrado correctamente.',
 87→                'reference_code' => $referenceCode,
 88→                'calves' => $createdCalves,
 89→                'new_capacity' => $subExploitation->fresh()->current_capacity,
 90→            ]);
 91→        });
 92→    }
 93→
 94→    /**
 95→     * Generate a mock reference code in format NC-2026-048-XXXXX.
 96→     */
 97→    private function generateReferenceCode(): string
 98→    {
 99→        $year = now()->year;
100→        $sequence = str_pad((string) random_int(1, 99999), 5, '0', STR_PAD_LEFT);
101→
102→        return "NC-{$year}-048-{$sequence}";
103→    }
104→
105→    /**
106→     * Generate a mock crotal code in format ES + 13 digits.
107→     */
108→    private function generateCrotalCode(): string
109→    {
110→        $digits = str_pad((string) random_int(0, 9999999999999), 13, '0', STR_PAD_LEFT);
111→
112→        return "ES{$digits}";
113→    }
114→}
